refentry.refsect1:
&reftitle.description;
public static staticReflectionMethod::createFromMethodName stringmethod
Creates a new ReflectionMethod.

&reftitle.parameters;




   method


     Class name and method name delimited by ::.

  &reftitle.examples;

    ReflectionMethod::createFromMethodName example


<?php

class Foo {
    public function bar() {

    }
}

$methodInfo = ReflectionMethod::createFromMethodName("Foo::bar");
var_dump($methodInfo);
?>


    &example.outputs;


object(ReflectionMethod)#1 (2) {
  ["name"]=>
  string(3) "bar"
  ["class"]=>
  string(3) "Foo"
}
